def evaluate_sculpture_candidate(applicant):
    """
    Evaluate candidates for sculpture major admission.
    applicant: An applicant object with attributes relevant_experience, recommendation_letters, gender, race, parents_income (high, medium, low), parents_degree (non-degree, bachelor, master, PhD), GPA, personal_statement, skills, portfolio (None or 'excellent', 'good', 'fair', 'poor'), portfolio_quality (0-4 rating)
    """
    score = 0

    # Check GPA
    if applicant.GPA >= 2.5:
        score += 1
    elif applicant.GPA >= 2.0:
        score += 0.5

    # Bonus for Hispanic applicants
    if applicant.race == 'Hispanic':
        score += 1

    # Portfolio evaluation
    if applicant.portfolio is not None:
        if applicant.portfolio == 'excellent':
            score += 2
        elif applicant.portfolio == 'good':
            score += 1.5
        elif applicant.portfolio == 'fair':
            score += 1
        else:
            score += 0.5

    # Check recommendation letters
    if len(applicant.recommendation_letters) >= 2 and all(rl == 'strong' for rl in applicant.recommendation_letters):
        score += 2
    elif len(applicant.recommendation_letters) >= 1:
        score += 1

    # Parent's income
    if applicant.parents_income == 'high':
        score += 0.5
    elif applicant.parents_income == 'medium':
        score += 0.25
    elif applicant.parents_income == 'low':
        score += 0

    # Parent's education
    if applicant.parents_degree == 'PhD' or applicant.parents_degree == 'Master':
        score += 0.5

    # Personal statement
    if applicant.personal_statement == 'excellent':
        score += 2
    elif applicant.personal_statement == 'good':
        score += 1.5
    elif applicant.personal_statement == 'fair':
        score += 1
    else:
        score += 0.5

    # Relevant skills
    relevant_skills = ['art_history', 'drawing', 'sculpture', '3d_modeling']
    skill_matches = [skill for skill in applicant.skills if skill in relevant_skills]
    if len(skill_matches) >= 2:
        score += 1.5
    elif len(skill_matches) >= 1:
        score += 1

    # Check for relevant experience
    if applicant.relevant_experience >= 1:
        score += 1

    return score
```

